def lcs(a, b):
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a)):
        for j in range(len(b)):
            dp[i+1][j+1] = dp[i][j] + 1 if a[i] == b[j] else max(dp[i][j+1], dp[i+1][j])
    return dp[-1][-1]

def rouge_l(a, b):
    a, b = a.lower().split(), b.lower().split()
    m = lcs(a, b)
    return 0.0 if m == 0 else 2 * m / (len(a) + len(b))

pool = ["Write a poem about rain", "Sort a list of numbers"]
candidates = ["Write a short poem about rain",
              "Translate this sentence to French",
              "Sort a list of numbers in reverse"]
for c in candidates:
    best = max(rouge_l(c, p) for p in pool)
    if best < 0.7:
        pool.append(c)
    print(c, round(best, 2), len(pool))
